import { preview } from 'vite';
import { chromium, expect } from '@playwright/test';
import { readFile, writeFile } from 'node:fs/promises';
import { PARAM_DEFS } from '../../src/tuning/schema';
const result: any = { revision: '54a429695ce197be59cde999d33911c080529286', startedAt: new Date().toISOString(), viewport: { width: 800, height: 450 } };
const save = async (stage: string) => { await writeFile('scratch/r6/probe.json', JSON.stringify(result, null, 2)); console.log(stage, JSON.stringify(result[stage] ?? {})); };
const server = await preview({ preview: { host: '127.0.0.1', port: 4190, strictPort: true } });
const browser = await chromium.launch({ headless: true, args: ['--enable-unsafe-swiftshader'] });
const watchdog = setTimeout(() => { console.error('Probe exceeded 10 minute watchdog'); process.exit(2); }, 600000);
try {
  result.browser = browser.version();
  const page = await browser.newPage({ viewport: result.viewport, acceptDownloads: true });
  page.setDefaultTimeout(60000);
  result.errors = [];
  page.on('pageerror', error => result.errors.push(error.message));
  page.on('console', msg => { if (msg.type() === 'error') result.errors.push(msg.text()); });
  await page.goto('http://127.0.0.1:4190/');
  await page.waitForFunction(() => window.__game?.ready);
  await page.getByLabel('Driving view').focus();
  await page.keyboard.press('KeyP');
  await expect.poll(() => page.evaluate(() => window.__game.getTelemetry().paused)).toBe(true);
  await page.keyboard.press('KeyO');
  await expect(page.locator('.sl-options')).toHaveAttribute('data-open','true');
  await page.keyboard.press('KeyH');
  await expect(page.locator('.sl-hud')).toHaveAttribute('data-mode','minimal');
  await expect(page.locator('[data-reading=fps]')).toBeVisible();
  await page.keyboard.press('KeyT');
  await expect.poll(() => page.evaluate(() => window.__game.tuning.get('timeScale'))).toBe(0.25);
  await page.keyboard.press('KeyT');
  await expect.poll(() => page.evaluate(() => window.__game.tuning.get('timeScale'))).toBe(1);
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button',{name:'Activate slot B'})).toHaveAttribute('aria-pressed','true');
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button',{name:'Activate slot A'})).toHaveAttribute('aria-pressed','true');
  result.mounts = { options: await page.locator('.sl-options').count(), hud: await page.locator('.sl-hud').count(), scriptsType: await page.evaluate(() => typeof window.__game.scripts), minimalFpsText: await page.locator('[data-reading=fps]').innerText(), hotkeys: ['P pauses','O opens','H selects Minimal','T toggles 0.25/1','Tab swaps A/B'] };
  await save('mounts');
  result.bindings = await page.evaluate(defs => {
    const game = window.__game, changes: any[] = [];
    for (const range of document.querySelectorAll<HTMLInputElement>('.sl-field input[type=range]')) {
      const key = range.closest<HTMLElement>('[data-key]')!.dataset.key!;
      const def = defs.find(d => d.key === key)!;
      const original = range.value;
      const useMax = Number(range.value) !== Number(range.max);
      range.value = useMax ? range.max : range.min;
      range.dispatchEvent(new Event('input',{bubbles:true}));
      const expected = useMax ? def.max : def.min;
      changes.push({ id: range.id, key, expected, actual: game.tuning.get(key), synchronous: Math.abs(game.tuning.get(key) - expected) < 1e-9 });
      range.value = original;
      range.dispatchEvent(new Event('input',{bubbles:true}));
    }
    game.tuning.applyPreset('Default');
    game.stepMany(0);
    return { count: changes.length, uniqueKeys: new Set(changes.map(c=>c.key)).size, mismatches: changes.filter(c=>!c.synchronous), changes };
  }, PARAM_DEFS.map(d=>({key:d.key,min:d.min,max:d.max})));
  expect(result.bindings.mismatches).toEqual([]);
  expect(result.bindings.uniqueKeys).toBe(PARAM_DEFS.length);
  await save('bindings');
  result.acceleration = await page.evaluate(() => {
    const game=window.__game, results:any[]=[];
    for (const value of [6,30]) {
      game.tuning.applyPreset('Default'); game.respawn();
      game.setInput({throttle:0,brake:0,steer:0,handbrake:false,boost:false}); game.stepMany(360);
      game.setInput({throttle:1}); game.stepMany(120);
      const before=Number(game.getTelemetry().speed);
      const field=document.querySelector<HTMLInputElement>('#group-accel0-number')!;
      field.value=String(value); field.dispatchEvent(new Event('input',{bubbles:true}));
      const applied=game.tuning.get('accel0');
      game.stepMany(1);
      const after=Number(game.getTelemetry().speed);
      results.push({value,applied,before,after,deltaSpeed:after-before});
    }
    return results;
  });
  expect(result.acceleration[1].deltaSpeed).toBeGreaterThan(result.acceleration[0].deltaSpeed);
  await save('acceleration');
  result.mass = [];
  for (const target of [1800,1300,1800]) {
    result.mass.push(await page.evaluate(async target => {
      const game=window.__game, before=game.getTelemetry();
      const field=document.querySelector<HTMLInputElement>('#group-mass-number')!;
      const began=performance.now();
      field.value=String(target); field.dispatchEvent(new Event('input',{bubbles:true}));
      return await new Promise(resolve=>{
        const poll=setInterval(()=>{
          const after=game.getTelemetry();
          if(after.mass===target || performance.now()-began>3000) {
            clearInterval(poll);
            resolve({target,actual:after.mass,elapsedMs:performance.now()-began,beforePosition:before.position,afterPosition:after.position,beforeSpeed:before.speed,afterSpeed:after.speed,status:after.massRebuildStatus});
          }
        },1);
      });
    }, target));
  }
  await save('mass');
  await page.waitForTimeout(300);
  await page.reload(); await page.waitForFunction(()=>window.__game?.ready);
  result.persistence = await page.evaluate(()=>({tuningMass:window.__game.tuning.get('mass'),bodyMass:window.__game.getTelemetry().mass}));
  expect(result.persistence).toEqual({tuningMass:1800,bodyMass:1800});
  await page.getByLabel('Driving view').focus(); await page.keyboard.press('KeyP');
  await expect.poll(()=>page.evaluate(()=>window.__game.getTelemetry().paused)).toBe(true);
  await page.keyboard.press('F9');
  await expect(page.locator('.sl-hud__recording')).toContainText('REC');
  await page.evaluate(()=>window.__game.stepMany(24));
  const pendingDownload=page.waitForEvent('download');
  await page.keyboard.press('F9');
  const download=await pendingDownload;
  const csv=(await readFile((await download.path())!,'utf8')).trim().split('\n');
  result.csv={sampleCount:JSON.parse(csv[0].slice(2)).sampleCount,lines:csv.length};
  expect(result.csv).toEqual({sampleCount:24,lines:26});
  await save('persistence'); await save('csv');
  const handbrake=JSON.parse(await readFile('src/input/examples/handbrake-turn.json','utf8'));
  result.replay=await page.evaluate(script=>{
    const game=window.__game, runs:any[]=[];
    for(let i=0;i<2;i++){
      game.scripts!.load(script,{tuning:i===0?'apply':'verify'}); game.stepMany(script.durationSteps+10);
      const terminal=game.getTelemetry(), progress={...game.scripts!.progress()};
      runs.push({result:structuredClone(game.scripts!.result()),progress,position:terminal.position,rotation:terminal.rotation,velocity:terminal.velocity,angularVelocity:terminal.angularVelocity,wheels:terminal.wheels,recoveryCount:terminal.recoveryCount});
      const steps=game.getTelemetry().totalSteps; game.stepMany(10);
      if(game.getTelemetry().totalSteps!==steps) throw Error('EOF advanced');
    }
    return {durationSteps:script.durationSteps,exactEqual:JSON.stringify(runs[0])===JSON.stringify(runs[1]),runs};
  },handbrake);
  expect(result.replay.exactEqual).toBe(true);
  await save('replay');
  const standing=JSON.parse(await readFile('src/input/examples/standing-start.json','utf8'));
  result.timeScales=[];
  for (const timeScale of [0.05,0.5,1,2]) {
    const script={...standing,name:'R6 rate probe',durationSteps:120,tuning:{...standing.tuning,timeScale},frames:[{step:0,input:{throttle:1,brake:0,steer:0,handbrake:false,boost:false,source:'keyboard'}}]};
    const began=Date.now();
    await page.evaluate(script=>{window.__game.setOptionsOpen(false);window.__game.scripts!.load(script,{tuning:'apply'});},script);
    await page.waitForFunction(()=>window.__game.scripts!.progress().done,undefined,{timeout:240000});
    const capture=await page.evaluate(()=>({progress:{...window.__game.scripts!.progress()},result:structuredClone(window.__game.scripts!.result()),telemetry:window.__game.getTelemetry()}));
    result.timeScales.push({timeScale,wallMs:Date.now()-began,progress:capture.progress,result:capture.result,recoveryCount:capture.telemetry.recoveryCount,physicsHz:capture.telemetry.physicsHz,position:capture.telemetry.position,velocity:capture.telemetry.velocity,rotation:capture.telemetry.rotation});
    await save('timeScales');
  }
  result.timeScaleStatesEqual=result.timeScales.every((v:any)=>JSON.stringify(v.result)===JSON.stringify(result.timeScales[0].result));
  expect(result.timeScaleStatesEqual).toBe(true);
  expect(result.errors).toEqual([]);
  result.completedAt=new Date().toISOString(); result.passed=true; await save('passed');
} catch(error) {
  result.failure=String(error); await save('failure'); process.exitCode=1;
} finally {
  clearTimeout(watchdog); await browser.close(); await new Promise(resolve=>server.httpServer.close(resolve));
}

