import { preview } from 'vite';
import { chromium } from '@playwright/test';
import { writeFile } from 'node:fs/promises';
const server=await preview({preview:{host:'127.0.0.1',port:4191,strictPort:true}});
const browser=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader']});
const report:any={revision:'54a429695ce197be59cde999d33911c080529286',method:'Timestamp the native 100 ms timer callback before and after it applies mass; no polling timer in the measured interval.',runs:[]};
const watchdog=setTimeout(()=>process.exit(2),180000);
try {
 const page=await browser.newPage({viewport:{width:800,height:450}});
 await page.goto('http://127.0.0.1:4191/');
 await page.waitForFunction(()=>window.__game?.ready,undefined,{timeout:60000});
 await page.evaluate(()=>{window.__game.perf!.pauseSimulation(true);window.__game.setOptionsOpen(true);window.__game.setHudMode('minimal');});
 for(const target of [1800,1300,1800]){
  const sample=await page.evaluate(async target=>{
   const game=window.__game,nativeTimeout=window.setTimeout;
   const before=game.getTelemetry(),began=performance.now();
   return await new Promise(resolve=>{
    window.setTimeout=((fn:any,delay:number,...args:any[])=>nativeTimeout((...passed:any[])=>{
     const callbackStart=performance.now();
     fn(...passed);
     const callbackEnd=performance.now();
     if(delay===100 && game.getTelemetry().mass===target) {
      const after=game.getTelemetry();
      resolve({target,requestedDelayMs:delay,callbackStartMs:callbackStart-began,callbackEndMs:callbackEnd-began,callbackDurationMs:callbackEnd-callbackStart,positionPreserved:JSON.stringify(before.position)===JSON.stringify(after.position),speedPreserved:before.speed===after.speed,frameMs:after.smoothedFrameMs});
     }
    },delay,...args)) as typeof window.setTimeout;
    try {
     const input=document.querySelector<HTMLInputElement>('#group-mass-number')!;
     input.value=String(target);input.dispatchEvent(new Event('input',{bubbles:true}));
    } finally {window.setTimeout=nativeTimeout;}
    nativeTimeout(()=>resolve({target,timeout:true}),20000);
   });
  },target);
  report.runs.push(sample);console.log(JSON.stringify(sample));
 }
 await writeFile('scratch/r6/mass-timer.json',JSON.stringify(report,null,2));
} finally {clearTimeout(watchdog);await browser.close();await new Promise(resolve=>server.httpServer.close(resolve));}

