import { it } from 'vitest';
import { readFile, writeFile } from 'node:fs/promises';
import assert from 'node:assert/strict';
import { scriptVehicleHarness } from './scriptVehicleHarness';
import { FixedStepLoop } from '../src/core/loop';
it('R6: timeScale on real vehicle frame schedules', async () => {
const source=JSON.parse(await readFile('src/input/examples/handbrake-turn.json','utf8'));
const results:any[]=[];
let reference:string|undefined;
for(const displayHz of [60,144]) for(const timeScale of [0.05,0.5,1,2]) {
 const rig=await scriptVehicleHarness();
 const script={...source,tuning:{...source.tuning,timeScale}};
 const dts=new Set<number>(); let interpolationValid=true;
 const loop=new FixedStepLoop({physicsHz:120,timeScale},{
  shouldStopStepping:()=>!rig.scripts.canStep(),
  sampleForStep:()=>{rig.mapper.sampleForStep();},
  preStep:dt=>{dts.add(dt);rig.vehicle.preStep(dt,rig.mapper.state,rig.mapper.state.source);},
  stepPhysics:dt=>rig.world.step(dt),
  postStep:dt=>{rig.vehicle.postStep(dt);rig.scripts.afterStep();},
  render:alpha=>{interpolationValid &&= alpha>=0 && alpha<1;},
 });
 try {
  rig.scripts.load(script,{tuning:'apply'});
  let frame=0;loop.frame(0);
  while(!rig.scripts.progress().done && frame<50000) loop.frame(++frame*1000/displayHz);
  const result=rig.scripts.result();
  const state=JSON.stringify({result,velocity:rig.vehicle.telemetry.velocity,angularVelocity:rig.vehicle.telemetry.angularVelocity,wheels:rig.vehicle.telemetry.wheels});
  reference ??= state;
  assert.equal(state,reference);assert.equal(result.allFinite,true);
  assert.equal(rig.vehicle.telemetry.recoveryCount,0);
  assert.equal(loop.totalSteps,script.durationSteps);
  assert.deepEqual([...dts],[1/120]);assert.equal(interpolationValid,true);
  const expectedSeconds=script.durationSteps/120/timeScale;
  assert.ok(Math.abs(frame/displayHz-expectedSeconds)<=1/displayHz+1e-9);
  results.push({displayHz,timeScale,frames:frame,virtualWallSeconds:frame/displayHz,expectedWallSeconds:expectedSeconds,physicsSteps:loop.totalSteps,dt:[...dts],allFinite:result.allFinite,recoveryCount:rig.vehicle.telemetry.recoveryCount,interpolationValid,exactStateEqual:true});
  console.log(JSON.stringify(results.at(-1)));
 } finally {rig.dispose();}
}
await writeFile('scratch/r6/time-scale.json',JSON.stringify({scope:'Real Jolt Vehicle + InputMapper + ScriptController + FixedStepLoop; synthetic frame schedules, no renderer or physical display claim.',results},null,2));

}, 90000);
